import{_ as t,o,c as a,a2 as n}from"./chunks/framework.BS0bAV7E.js";const m=JSON.parse('{"title":"The TUI engine","description":"","frontmatter":{},"headers":[],"relativePath":"arch/tui-engine.md","filePath":"arch/tui-engine.md"}'),r={name:"arch/tui-engine.md"};function i(d,e,c,s,h,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="the-tui-engine" tabindex="-1">The TUI engine <a class="header-anchor" href="#the-tui-engine" aria-label="Permalink to &quot;The TUI engine&quot;">​</a></h1><p><code>tui/</code> is a windowing system on the framebuffer console:</p><h2 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h2><p><code>tui_core.c</code> (the event loop + window manager), <code>tui_win.c</code> (windows), <code>tui_menu.c</code>, <code>tui_form.c</code>, <code>tui_panel.c</code>, <code>tui_text.c</code> (widgets), <code>tui_input.c</code> (keyboard routing), <code>tui_hw.c</code> (render diagnostics).</p><h2 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h2><p><code>tui_desktop.c</code> + <code>tui_dt_*</code>: taskbar, launcher, the apps (files, editor, process/system monitor, network status, sysinfo, clock).</p><h2 id="the-command-bridge" tabindex="-1">The command bridge <a class="header-anchor" href="#the-command-bridge" aria-label="Permalink to &quot;The command bridge&quot;">​</a></h2><p><code>tui_cmd.c</code> enumerates the shell command table through the L1 API (any L1 module may enumerate - <code>l1_ext_shell_list_commands_a_z</code>) and renders it as the launcher: the reference consumer of the extension surface.</p><h2 id="extension-surface" tabindex="-1">Extension surface <a class="header-anchor" href="#extension-surface" aria-label="Permalink to &quot;Extension surface&quot;">​</a></h2><p><code>tui_ext.h</code> - 37 callable declarations (windows, menus, forms, panels, text). L1 modules build UI through it; the CN variants (<code>tui_cn_*.c</code>) show the pattern with the Chinese layer under them.</p><h2 id="rendering-path" tabindex="-1">Rendering path <a class="header-anchor" href="#rendering-path" aria-label="Permalink to &quot;Rendering path&quot;">​</a></h2><p>Framebuffer geometry comes from the multiboot2 framebuffer tag; the console grid and the 8x16 font engine come up before the IDT does (the boot log order matters - the TUI draws with the same primitives the kernel banner used). <code>tui-test</code> is the in-guest regression suite for all of it.</p>',12)])])}const p=t(r,[["render",i]]);export{m as __pageData,p as default};
